import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash, randomUUID } from 'node:crypto';
import { resolve } from 'node:path';
import { Tracer } from '../../src/index.ts';
import { SQLiteRepository } from '../../src/persistence/sqlite.ts';
import { observeLocal } from '../../src/interfaces/local-observer.ts';

const journal = 'output/configuration-change/original-follow-through-prepared.json';
assert.ok(!existsSync(journal), 'Inspect saved original intent before any attempted recovery');
const state = {};
const save = extra => writeFileSync(journal, JSON.stringify({ ...state, ...extra }, null, 2) + '\n');
const actor = { actor: 'tracer-configuration-change', reason: 'Prepare original actual REQ-035 capture-enhancement pair with genuine pre-edit states; no full acceptance outcome claimed.' };
const repository = new SQLiteRepository('projects/tracer/tracer.sqlite');
try {
  const t = new Tracer(repository, undefined, observeLocal);
  const initial = await t.exportProject();
  assert.equal(initial.projectRevision, 163);
  const original = JSON.parse(readFileSync('projects/tracer/configuration-change-original-case.json'));
  const snapshot = await t.getProjectSnapshot();
  const req = snapshot.entities.find(x => x.key === 'REQ-035');
  const method = snapshot.entities.find(x => x.key === 'VER-035');
  const subject = snapshot.entities.find(x => x.key === 'COMP-APP');
  const model = snapshot.entities.find(x => x.key === 'MODEL-REQUIREMENT-VERIFICATION');
  assert.equal(model.version, 1);
  assert.equal(method.version, 1);
  state.originalLegacy = await t.configurations.get(original.legacyConfiguration.id);
  state.originalAcceptance = req.fields.acceptance;
  const paths = ['projects/tracer/configuration-final-candidate-manifest.json', 'projects/tracer/configuration-original-follow-through-method.json'];
  const materials = paths.map(path => {
    assert.ok(!snapshot.entities.some(x => x.resource?.source?.externalId === path));
    return { path, id: randomUUID() };
  });
  const command = { commandId: 'configuration-original-final-materials-2026-10-28', expectedSchemaVersion: 7, expectedProjectRevision: 163, operations: materials.map(x => ({ op: 'entity.create', id: x.id, input: { type: '@resource', fields: {}, resource: { label: x.path, source: { system: 'file', externalId: x.path } } } })) };
  state.materials = materials;
  state.materialCommand = command;
  save({ pending: command });
  state.materialResult = await t.applyChangeset(command, actor);
  save({});
  const relationships = original.legacyConfiguration.relationships.map(x => ({ relationshipId: x.relationshipId, version: x.version }));
  const native = [subject, req, method, model];
  const scope = { purpose: 'Actual original REQ-035 configuration capture enhancement and complete selected capability audit', coverage: 'partial', rationale: 'Explicit component/requirement/method/interpretation and seven original source resources. Before is a retrospective reconstruction using genuine historical pins and pre-edit observations, not an edit of legacy captures. After additionally selects exact candidate inventory/procedure. Other engineering dependencies and unselected bytes remain unknown.' };
  const request = async (name, members, content) => {
    const context = await t.configurations.captureContext();
    return { id: randomUUID(), name, subjectId: subject.id, expectedSubjectVersion: subject.version, members, relationships, content, scope, expectedSchemaVersion: context.schema.version, expectedProjectRevision: context.projectRevision, expectedEvidenceRevision: context.evidenceRevision };
  };
  const oldResources = original.sourceStates.map(x => {
    const current = snapshot.entities.find(e => e.id === x.id);
    assert.ok(current);
    assert.equal(current.version, 1);
    return { ...x, version: 1 };
  });
  state.beforeInput = await request('Original configuration capture enhancement — retrospective pre-edit scope', [...native.map(x => ({ entityId: x.id, version: 1 })), ...oldResources.map(x => ({ entityId: x.id, version: x.version }))], oldResources.map(x => ({ entityId: x.id, observationId: x.observationId })));
  save({ pending: state.beforeInput });
  state.before = await t.configurations.captureExact(state.beforeInput, actor);
  save({});
  const observed = [];
  for (const x of [...oldResources, ...materials.map(x => ({ ...x, version: 1 }))]) {
    const observation = await t.evidence.observe({ entityId: x.id, locator: { system: 'file', path: resolve(x.path) } }, actor);
    assert.equal(observation.hash, 'sha256:' + createHash('sha256').update(readFileSync(x.path)).digest('hex'));
    observed.push({ path: x.path, id: x.id, version: x.version, observation });
    state.observed = observed;
    save({});
  }
  state.afterInput = await request('Original configuration enhancement — exact final candidate scope', [...native.map(x => ({ entityId: x.id, version: x.version })), ...observed.map(x => ({ entityId: x.id, version: x.version }))], observed.map(x => ({ entityId: x.id, observationId: x.observation.id })));
  save({ pending: state.afterInput });
  state.after = await t.configurations.captureExact(state.afterInput, actor);
  save({});
  state.comparison = await t.configurations.compare({ beforeId: state.before.id, afterId: state.after.id });
  const context = await t.applicationModels.resolve({ entityId: '8e702928-56c6-4bcf-95bf-94ef0f334bd5', version: 1, field: 'definition' });
  state.opening = { commandId: 'configuration-original-final-assessment-open-2026-10-28', assessmentId: randomUUID(), title: 'Assess original actual configuration-capture enhancement', purpose: 'Complete original REQ-035 acceptance on the exact final candidate; retain partial historical proofs, unknown external scope and original conclusions. Full controlled verification remains required.', model: context.pin, query: { source: 'configuration_pair', beforeId: state.before.id, afterId: state.after.id, policy: 'scoped-reference-dependencies-v1', rootId: req.id, direction: 'outgoing', relationshipTypes: [], depth: 1 }, additionalFields: {}, expectedSchemaVersion: context.context.schemaVersion, expectedProjectRevision: context.context.projectRevision, expectedEvidenceRevision: context.context.evidenceRevision };
  save({ pending: state.opening });
  state.opened = await t.changeAssessments.open(state.opening, actor);
  state.selection = { assessmentId: state.opening.assessmentId, openingCommandId: state.opening.commandId };
  state.analysis = await t.changeAssessments.analyze(state.selection);
  assert.deepEqual(await t.configurations.get(original.legacyConfiguration.id), state.originalLegacy);
  assert.equal((await t.getEntity(req.id)).fields.acceptance, state.originalAcceptance);
  save({ status: 'original_real_pair_prepared_full_acceptance_pending', nativeRevision: (await t.exportProject()).projectRevision });
  console.log(JSON.stringify({ before: state.before.id, after: state.after.id, assessment: state.selection, candidates: state.analysis.obligations.length, nativeRevision: (await t.exportProject()).projectRevision }));
} finally { repository.close(); }
